	"github.com/stretchr/testify/require"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/credentials"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/dynamodb"
)

type mockDynamo struct {
	mu       sync.Mutex
	requests []mockRequest
	// scanPages is a list of pages, each page is a list of items
	scanPages []map[string]interface{}
	// queryItems items returned for each Query call
	queryItems []map[string]interface{}
	// indexes returned by DescribeTable
	indexes []string
}

type mockRequest struct {
	Operation string
	Body      map[string]interface{}
}

func (m *mockDynamo) handler(t *testing.T) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		target := r.Header.Get("X-Amz-Target")
		op := target[strings.LastIndex(target, ".")+1:]
		data, err := ioutil.ReadAll(r.Body)
		require.NoError(t, err)
		var body map[string]interface{}
		require.NoError(t, json.Unmarshal(data, &body))

		m.mu.Lock()
		defer m.mu.Unlock()
		m.requests = append(m.requests, mockRequest{Operation: op, Body: body})

		var out interface{}
		switch op {
		case "Scan":
			page := map[string]interface{}{"Items": []map[string]interface{}{}}
			if len(m.scanPages) > 0 {
				page = map[string]interface{}{}
				for k, v := range m.scanPages[0] {
					page[k] = v
				}
				m.scanPages = m.scanPages[1:]
				if len(m.scanPages) == 0 && page["LastEvaluatedKey"] != nil {
					// last page should not carry a key forever
					delete(page, "LastEvaluatedKey")
				}
			}
			out = page
		case "Query":
			items := m.queryItems
			m.queryItems = nil
			out = map[string]interface{}{"Items": items}
		case "DescribeTable":
			indexes := []map[string]interface{}{}
			for _, idx := range m.indexes {
				indexes = append(indexes, map[string]interface{}{
					"IndexName": idx,
					"IndexStatus": "ACTIVE",
				})
			}
			out = map[string]interface{}{
				"Table": map[string]interface{}{
					"TableName":              body["TableName"],
					"TableStatus":            "ACTIVE",
					"GlobalSecondaryIndexes": indexes,
				},
			}
		default:
			out = map[string]interface{}{}
		}
		enc, err := json.Marshal(out)
		require.NoError(t, err)
		w.Header().Set("Content-Type", "application/x-amz-json-1.0")
		w.WriteHeader(http.StatusOK)
		w.Write(enc)
	})
}

func newMockLog(t *testing.T, m *mockDynamo) (*Log, func()) {
	srv := httptest.NewServer(m.handler(t))
	sess, err := session.NewSession(&aws.Config{
		Region:      aws.String("us-west-2"),
		Credentials: credentials.NewStaticCredentials("key", "secret", ""),
		Endpoint:    aws.String(srv.URL),
	})
	require.NoError(t, err)
	l := &Log{
		Entry: log.NewEntry(),
		Config: Config{
			Tablename:    "events",
			Clock:        clockwork.NewFakeClock(),
			UIDGenerator: utils.NewFakeUID(),
		},
		svc: dynamodb.New(sess),
	}
	return l, srv.Close
}

func attrTypes(values map[string]interface{}) (numStrings, numNumbers int) {
	for _, v := range values {
		m := v.(map[string]interface{})
		if _, ok := m["S"]; ok {
			numStrings++
		}
		if _, ok := m["N"]; ok {
			numNumbers++
		}
	}
	return
}

func TestScratchDaysBetween(t *testing.T) {
	days := daysBetween(
		time.Date(2020, 1, 30, 23, 0, 0, 0, time.UTC),
		time.Date(2020, 2, 2, 1, 0, 0, 0, time.UTC))
	require.Equal(t, []string{"2020-01-30", "2020-01-31", "2020-02-01", "2020-02-02"}, days)

	// single day
	require.Equal(t, []string{"2020-02-29"}, daysBetween(
		time.Date(2020, 2, 29, 0, 0, 0, 0, time.UTC),
		time.Date(2020, 2, 29, 23, 59, 59, 0, time.UTC)))

	// year boundary
	require.Equal(t, []string{"2019-12-31", "2020-01-01"}, daysBetween(
		time.Date(2019, 12, 31, 5, 0, 0, 0, time.UTC),
		time.Date(2020, 1, 1, 5, 0, 0, 0, time.UTC)))

	// reversed range yields nothing
	require.Empty(t, daysBetween(time.Now(), time.Now().Add(-time.Hour)))
}

func TestScratchMigrateDateAttribute(t *testing.T) {
	m := &mockDynamo{scanPages: []map[string]interface{}{
		{
			"Items": []map[string]interface{}{
				{
					"SessionID":  map[string]interface{}{"S": "session-1"},
					"EventIndex": map[string]interface{}{"N": "1"},
					"CreatedAt":  map[string]interface{}{"N": "1580000000"}, // 2020-01-25
					"Fields":     map[string]interface{}{"S": "{}"},
				},
			},
			"LastEvaluatedKey": map[string]interface{}{
				"SessionID":  map[string]interface{}{"S": "session-1"},
				"EventIndex": map[string]interface{}{"N": "1"},
			},
		},
		{
			"Items": []map[string]interface{}{
				{
					"SessionID":  map[string]interface{}{"S": "session-2"},
					"EventIndex": map[string]interface{}{"N": "2"},
					"CreatedAt":  map[string]interface{}{"N": "1583000000"}, // 2020-02-29
					"Fields":     map[string]interface{}{"S": "{}"},
				},
			},
		},
	}}
	l, closeFn := newMockLog(t, m)
	defer closeFn()

	require.NoError(t, l.migrateDateAttribute(context.Background()))

	var scans, updates int
	for _, req := range m.requests {
		switch req.Operation {
		case "Scan":
			scans++
		case "UpdateItem":
			updates++
			key := req.Body["Key"].(map[string]interface{})
			require.Len(t, key, 2)
			require.Contains(t, key, "SessionID")
			require.Contains(t, key, "EventIndex")
			require.NotNil(t, key["SessionID"].(map[string]interface{})["S"])
			require.NotNil(t, key["EventIndex"].(map[string]interface{})["N"])

			expr := req.Body["ExpressionAttributeValues"].(map[string]interface{})
			nstr, nnum := attrTypes(expr)
			require.Equal(t, 1, nstr, "migration update must bind exactly one string value")
			require.Equal(t, 0, nnum)
			for _, v := range expr {
				require.NotEmpty(t, v.(map[string]interface{})["S"])
			}
		default:
			t.Fatalf("migration issued unexpected operation %v", req.Operation)
		}
	}
	require.Equal(t, 2, scans)
	require.Equal(t, 2, updates)

	// dates must be derived per item
	dates := map[string]string{}
	for _, req := range m.requests {
		if req.Operation != "UpdateItem" {
			continue
		}
		sid := req.Body["Key"].(map[string]interface{})["SessionID"].(map[string]interface{})["S"].(string)
		for _, v := range req.Body["ExpressionAttributeValues"].(map[string]interface{}) {
			dates[sid] = v.(map[string]interface{})["S"].(string)
		}
	}
	require.Equal(t, "2020-01-25", dates["session-1"])
	require.Equal(t, "2020-02-29", dates["session-2"])

	// context cancellation is honored
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	require.Error(t, l.migrateDateAttribute(ctx))
}

func TestScratchIndexExists(t *testing.T) {
	m := &mockDynamo{indexes: []string{indexTimeSearch, indexTimeSearchV2}}
	l, closeFn := newMockLog(t, m)
	defer closeFn()

