func TestScratchSearchEventsQuery(t *testing.T) {
	m := &mockDynamo{queryItems: []map[string]interface{}{
		{
			"SessionID":      map[string]interface{}{"S": "session-1"},
			"EventIndex":     map[string]interface{}{"N": "1"},
			"CreatedAt":      map[string]interface{}{"N": "1580000000"},
			"CreatedAtDate":  map[string]interface{}{"S": "2020-01-25"},
			"EventNamespace": map[string]interface{}{"S": "default"},
			"Fields": map[string]interface{}{"S": `{"type":"session.start","time":"2020-01-25T00:00:00Z","index":1}`},
		},
	}}
	l, closeFn := newMockLog(t, m)
	defer closeFn()

	from := time.Date(2020, 1, 25, 0, 0, 0, 0, time.UTC)
	to := time.Date(2020, 1, 25, 12, 0, 0, 0, time.UTC)
	fields, err := l.SearchEvents(from, to, "", 0)
	require.NoError(t, err)
	require.Len(t, fields, 1)

	var queries int
	for _, req := range m.requests {
		if req.Operation != "Query" {
			t.Fatalf("unexpected operation %v", req.Operation)
		}
		queries++
		require.Equal(t, indexTimeSearchV2, req.Body["IndexName"])
		expr := req.Body["ExpressionAttributeValues"].(map[string]interface{})
		nstr, nnum := attrTypes(expr)
		require.Equal(t, 1, nstr, "must bind exactly one string value (the date)")
		require.Equal(t, 2, nnum, "must bind exactly two numeric values (CreatedAt bounds)")
		var foundDate string
		for _, v := range expr {
			if s, ok := v.(map[string]interface{})["S"]; ok {
				foundDate = s.(string)
			}
		}
		require.Equal(t, "2020-01-25", foundDate)
		kc, ok := req.Body["KeyConditionExpression"].(string)
		require.True(t, ok)
		t.Logf("KeyConditionExpression: %v", kc)
		require.False(t, strings.Contains(kc, "EventNamespace"))
	}
	require.Equal(t, 1, queries)

	// multi-day range issues one query per day, sorted results
	m.requests = nil
	m.queryItems = nil
	_, err = l.SearchEvents(from, from.AddDate(0, 0, 3), "", 0)
	require.NoError(t, err)
	var ops []string
	for _, req := range m.requests {
		ops = append(ops, req.Operation)
	}
	require.Equal(t, []string{"Query", "Query", "Query", "Query"}, ops)
}

